INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (100, "ヤマト", 2.1, -416.5, "2024/10/31 12:00:00", 3001, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 130011, 3001100, "2030/01/01 14:59:59", 0.0, 1, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (101, "ヤマト", 5.68, -416.5, "2024/10/31 12:00:00", 3001, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 130011, 3001101, "2030/01/01 14:59:59", 0.0, 4, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (102, "ヤマト", 0.0, -416.5, "2024/10/31 12:00:00", 3001, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 130011, 3001102, "2030/01/01 14:59:59", 0.0, 1, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (100, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3002, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 130211, 3002100, "2030/01/01 14:59:59", 0.0, 1, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (101, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3002, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 130211, 3002101, "2030/01/01 14:59:59", 0.0, 1, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (102, "フブキ", 8.53, -416.5, "2024/10/31 12:00:00", 3002, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 130211, 3002102, "2030/01/01 14:59:59", 0.0, 5, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (103, "フブキ", 5.67, -416.5, "2024/10/31 12:00:00", 3002, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 130211, 3002103, "2030/01/01 14:59:59", 0.0, 7, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (104, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3002, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 130211, 3002104, "2030/01/01 14:59:59", 0.0, 1, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (300, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3004, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 130211, 3002300, "2030/01/01 14:59:59", 0.0, 3, 3);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (301, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3005, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 130211, 3002400, "2030/01/01 14:59:59", 0.0, 7, 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (200, "フブキ", 4.4, -416.5, "2024/10/31 12:00:00", 3003, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 130211, 3003200, "2030/01/01 14:59:59", 0.0, 2, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (201, "フブキ", 0.0, -416.5, "2024/10/31 12:00:00", 3003, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 130211, 3003201, "2030/01/01 14:59:59", 0.0, 7, 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (202, "フブキ", 5.6, -416.5, "2024/10/31 12:00:00", 3003, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 130211, 3003202, "2030/01/01 14:59:59", 0.0, 1, 2);
